export function useGenerateTocLogic() {
  const { toast } = useToast();
  const { firebaseUser } = useAuth();

  const mutation = useMutation({
    mutationFn: async (data: FormValues): Promise<z.infer<typeof GenerateTocOutputSchema>> => {
      if (!firebaseUser) throw new Error('User not authenticated');
      const token = await firebaseUser.getIdToken();

      return writingToolApi<any, z.infer<typeof GenerateTocOutputSchema>>(
        '/api/writing-tools/generate-toc',
        {
          data: {
            projectDescription: data.projectDescription,
            additionalInstructions: data.additionalInstructions,
          },
          token
        }
      );
    },
    onSuccess: () => {
        toast({ title: "Table of Contents generated successfully!" });
    },
    onError: (error: Error) => {
      toast({
        title: 'Error generating TOC',
        description: error.message,
        variant: 'destructive',
      });
    },
  });

const analysisMutation = useMutation({
    mutationFn: async (variables: { prompt: string; contextFiles: any[]; token: string; }) => {
        const { analyzeContextApi } = await import('@/services');
        return analyzeContextApi({
            prompt: variables.prompt,
            contextFiles: variables.contextFiles,
        }, variables.token);
    },
    onSuccess: (data) => {
        refetchUser(); // To update credits
        toast({ title: t('builder.files.toasts.analysisComplete'), description: t('builder.files.toasts.analysisCompleteDesc') });
        // After successful analysis, convert JSON to Markdown
        const markdown = jsonToMarkdown(data.data);
        setMarkdownResult(markdown);
    },
    onError: (error: Error) => {
        toast({ title: t('builder.files.toasts.analysisFailed'), description: error.message, variant: 'destructive' });
    }
});

